import pypdf
import pubchempy as pcp
from rdkit import Chem
from rdkit.Chem import AllChem

def test_extraction():
    print("Testing PDF extraction...")
    reader = pypdf.PdfReader('molecules.pdf')
    text = ""
    for page in reader.pages:
        text += page.extract_text() + "\n"

    names = [line.strip() for line in text.split('\n') if line.strip()]
    print(f"Found {len(names)} lines.")
    print(f"First 5: {names[:5]}")
    return names

def test_pubchem(name):
    print(f"Testing PubChem for {name}...")
    try:
        comps = pcp.get_compounds(name, 'name')
        if comps:
            smiles = comps[0].isomeric_smiles
            print(f"SMILES: {smiles}")
            return smiles
        else:
            print("No compound found.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    names = test_extraction()
    if names:
        test_pubchem(names[0])

