import pubchempy as pcp

def test_chirality():
    name = "L-Lactic acid"
    print(f"Testing PubChem for {name}...")
    try:
        comps = pcp.get_compounds(name, 'name')
        if comps:
            c = comps[0]
            print(f"Isomeric SMILES: {c.isomeric_smiles}")
            print(f"Canonical SMILES: {c.canonical_smiles}")
            # print(f"Smiles (deprecated?): {c.smiles}") 
        else:
            print("No compound found.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    test_chirality()

